export type ParsedCoverBadDebtInstruction<
  TProgram extends string = typeof BACKSTOP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    /** Owned by the lending vault program, so its bad-debt counter cannot be fabricated. */
    market: TAccountMetas[1];
    cover: TAccountMetas[2];
    marketUsdcVault: TAccountMetas[3];
    usdcMint: TAccountMetas[4];
    usdcVault: TAccountMetas[5];
    usdcTokenProgram: TAccountMetas[6];
  };
  data: CoverBadDebtInstructionData;
};

export function parseCoverBadDebtInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCoverBadDebtInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      market: getNextAccount(),
      cover: getNextAccount(),
      marketUsdcVault: getNextAccount(),
      usdcMint: getNextAccount(),
      usdcVault: getNextAccount(),
      usdcTokenProgram: getNextAccount(),
    },
    data: getCoverBadDebtInstructionDataDecoder().decode(instruction.data),
  };
}
